   "constraints": []
  },
  {
   "name": "min_like_count",
   "type": "integer",
   "required": false,
   "description": "Minimum like count to filter transactions.",
   "default": 0,
   "constraints": []
  },
  {
   "name": "max_like_count",
   "type": "integer",
   "required": false,
   "description": "Maximum like count to filter transactions.",
   "default": 9223372036854775807,
   "constraints": []
  },
  {
   "name": "min_amount",
   "type": "number",
   "required": false,
   "description": "Minimum amount to filter transactions.",
   "default": 0,
   "constraints": [
    "value > 0.0"
   ]
  },
  {
   "name": "max_amount",
   "type": "number",
   "required": false,
   "description": "Maximum amount to filter transactions.",
   "default": 9223372036854775807,
   "constraints": [
    "value > 0.0"
   ]
  },
  {
   "name": "private",
